import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasW = 2048, atlasH = 2048;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;

  const planeH = 1.0;
  const planeW = planeH * aspect;
  const geometry = new THREE.PlaneGeometry(planeW, planeH);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const uOffset = rect.x / atlasW;
  const vOffset = 1 - (rect.y + rect.h) / atlasH;
  const uScale = rect.w / atlasW;
  const vScale = rect.h / atlasH;

  const uvNode = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));
  const mapNode = texture(map, uvNode);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = mapNode;

  const bgMesh = new THREE.Mesh(geometry, material);
  bgMesh.name = 'features-title-bg';
  group.add(bgMesh);

  let textMesh = null;
  if (ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
    textMesh = ctx.fontAtlas.createText({
      text: 'Features',
      font: 'display',
      weight: 400,
      size: 0.34,
      color: config?.colors?.ink ?? '#16161d',
      align: 'center',
      anchor: 'center'
    });
    textMesh.name = 'features-title-text';
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  }

  group.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
      if (typeof textMesh.userData?.cleanup === 'function') {
        textMesh.userData.cleanup();
      }
    }
  };

  return group;
}
